// VoxelRenderer Verilog (Verilator) vs the reference model (vr.c): scene/camera files (VOXEL_DUMP
// format: world, textures, blocks, struct vr_camera), whole 3D view, mismatches printed.
// Port names come from tb_ports.h (generated by test/test_voxel.py).

#include <cstdio>
#include <cstdlib>
#include <cstring>
#include <cstdint>

#include "Vvoxel.h"
#include "verilated.h"

#include "vr.h" /* vr.c is compiled as C++ by Verilator. */

#include "tb_ports.h"

static Vvoxel *top;

static void tick(void)
{
	top->sys_clk = 0; top->eval();
	top->sys_clk = 1; top->eval();
}

static void bus_write(uint32_t adr, uint32_t dat)
{
	BUS_ADR = adr; BUS_DAT_W = dat; BUS_WE = 1; BUS_SEL = 0xf; BUS_CYC = 1; BUS_STB = 1;
	do { tick(); } while (!BUS_ACK);
	BUS_CYC = 0; BUS_STB = 0; BUS_WE = 0;
	tick();
}

static uint32_t u16(int16_t v) { return (uint16_t)v; }

int main(int argc, char **argv)
{
	Verilated::commandArgs(argc, argv);
	top = new Vvoxel;
	int errors = 0;

	for (int arg = 1; arg < argc; arg++) {
		static uint32_t world[VR_WORLD_WORDS], textures[VR_TEXTURE_WORDS];
		static uint16_t blocks[VR_BLOCKS];
		struct vr_camera cam;
		FILE *f = fopen(argv[arg], "rb");
		if (!f || fread(world, sizeof(world), 1, f) != 1 || fread(textures, sizeof(textures), 1, f) != 1 ||
		    fread(blocks, sizeof(blocks), 1, f) != 1 || fread(&cam, sizeof(cam), 1, f) != 1) {
			fprintf(stderr, "%s: read error\n", argv[arg]);
			return 2;
		}
		fclose(f);

		/* Memories, parameters. */
		top->sys_rst = 1; tick(); top->sys_rst = 0; tick();
		for (int i = 0; i < VR_WORLD_WORDS; i++)   bus_write(i, world[i]);
		for (int i = 0; i < VR_TEXTURE_WORDS; i++) bus_write(0x1000 + i, textures[i]);
		for (int i = 0; i < VR_BLOCKS; i++)        bus_write(0x1800 + i, blocks[i]);
		ROWS      = 0 | VR_HEIGHT << 8;
		CELL      = cam.cx | cam.cy << 8 | cam.cz << 16;
		FRAC      = cam.fx | cam.fy << 8 | cam.fz << 16;
		FWD_XY    = u16(cam.fwd[0])   | u16(cam.fwd[1]) << 16;   FWD_Z   = u16(cam.fwd[2]);
		RIGHT_XY  = u16(cam.right[0]) | u16(cam.right[1]) << 16; RIGHT_Z = u16(cam.right[2]);
		DOWN_XY   = u16(cam.down[0])  | u16(cam.down[1]) << 16;  DOWN_Z  = u16(cam.down[2]);
		WINDOW    = cam.ox | cam.oz << 8;
		T_FAR     = cam.t_far;
		FOG_START = cam.fog_start;
		FOG       = (cam.fog_shift & 31) | cam.sky_base << 5;
		SELECT    = cam.sel_en | cam.sel_x << 1 | cam.sel_y << 9 | (uint32_t)cam.sel_z << 17;
		COLORS    = cam.sel_index | cam.cross_en << 8 | cam.cross_index << 9 | (cam.sel_shift & 31) << 17;

		/* Render (start pulse), lines captured from the line buffer writes/copy requests. */
		static uint8_t slots[4][VR_WIDTH], image[VR_HEIGHT][VR_WIDTH];
		CONTROL = 1 | 1 << 1; CONTROL_RE = 1; tick(); CONTROL_RE = 0; CONTROL = 1 << 1;
		int lines = 0;
		for (long cycle = 0; cycle < 50000000 && lines < VR_HEIGHT; cycle++) {
			if (FB_WE) {
				unsigned slot = FB_ADR/40, word = FB_ADR % 40;
				for (int b = 0; b < 4; b++)
					slots[slot][4*word + b] = (FB_DAT >> 8*b) & 0xff;
			}
			if (FB_LINE_VALID) {
				memcpy(image[FB_LINE_LINE], slots[FB_LINE_SLOT], VR_WIDTH);
				lines++;
			}
			tick();
		}
		const struct vr_scene scene = {world, textures, blocks};
		int mismatches = 0;
		for (int y = 0; y < VR_HEIGHT; y++) {
			uint8_t line[VR_WIDTH];
			vr_line(&scene, &cam, y, line);
			for (int x = 0; x < VR_WIDTH; x++)
				if (line[x] != image[y][x]) {
					if (mismatches < 10)
						printf("%s: (%d, %d) verilog %02x model %02x\n", argv[arg], x, y, image[y][x], line[x]);
					mismatches++;
				}
		}
		printf("%s: %d lines, %d mismatches, %lu cycles\n", argv[arg], lines, mismatches, (unsigned long)CYCLES);
		errors += mismatches + (lines != VR_HEIGHT);
	}
	delete top;
	return errors ? 1 : 0;
}
